namespace sv_044ac03f61f44e1399a7e523168b93b7.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static Dictionary<string, string> Warehouses { get; } = new()
    {
        ["WH-001"] = "Warehouse A — Main Distribution",
        ["WH-002"] = "Warehouse B — East Coast",
        ["WH-003"] = "Warehouse C — West Coast",
        ["WH-004"] = "Warehouse D — Returns Processing"
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_044ac03f61f44e1399a7e523168b93b7.Services;

public class InventoryAlertService : IAsyncDisposable
{
    private readonly WarehouseState _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query — returns a random number between 0 and 15
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _cts = new CancellationTokenSource();
                _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
                _ = PollLoopAsync(_cts.Token);
            }
        }
    }

    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount--;
            if (_subscriberCount <= 0)
            {
                _subscriberCount = 0;
                _cts?.Cancel();
                _timer?.Dispose();
                _timer = null;
                _cts?.Dispose();
                _cts = null;
            }
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAlertCountAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAlertCountAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAlertCountAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        CurrentAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh if polling is active
        if (_subscriberCount > 0)
        {
            _ = RefreshAlertCountAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _timer?.Dispose();
        if (_cts is not null)
        {
            _cts.Dispose();
        }
        await ValueTask.CompletedTask;
    }
}

