@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text">
                    @if (AlertService.CurrentAlertCount > 0)
                    {
                        <span class="fs-2 text-danger fw-bold">@AlertService.CurrentAlertCount</span>
                        <span class="text-muted ms-2">items below minimum levels</span>
                    }
                    else
                    {
                        <span class="fs-2 text-success fw-bold">0</span>
                        <span class="text-muted ms-2">all stock levels healthy</span>
                    }
                </p>
                <p class="text-muted small">
                    <em>Polling every 10 seconds (active while on this page)</em>
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">How This Works</h5>
                <ul>
                    <li>The <strong>warehouse selector</strong> in the top bar is shared across all pages via a scoped <code>WarehouseState</code> service.</li>
                    <li>The <strong>alert badge</strong> in the sidebar and the count above both subscribe to <code>InventoryAlertService.OnAlertCountChanged</code>.</li>
                    <li>Polling starts when you visit this page and stops when you navigate away.</li>
                    <li>Switching warehouses triggers an immediate refresh of the alert count.</li>
                    <li>Each user circuit has its own scoped service instances — no state leaks between users.</li>
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling when dashboard becomes visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

